PRAGMA foreign_keys = ON;
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE office (id TEXT PRIMARY KEY, name TEXT NOT NULL, location TEXT, email TEXT, sla_days INTEGER, description TEXT);
CREATE TABLE staff (id TEXT PRIMARY KEY, name TEXT NOT NULL, office_id TEXT NOT NULL REFERENCES office, title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','leave','departed')), manager_id TEXT REFERENCES staff, capacity INTEGER NOT NULL CHECK(capacity>0), department TEXT, email TEXT NOT NULL);
CREATE TABLE staff_absence (id TEXT PRIMARY KEY, staff_id TEXT NOT NULL REFERENCES staff, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, covering_staff_id TEXT NOT NULL REFERENCES staff, reason TEXT NOT NULL, CHECK(ends_at>starts_at), CHECK(staff_id<>covering_staff_id));
CREATE TABLE term (id TEXT PRIMARY KEY, name TEXT NOT NULL, starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, registration_opens TEXT NOT NULL, add_drop_at TEXT NOT NULL, census_at TEXT NOT NULL, CHECK(ends_on>starts_on));
CREATE TABLE program (id TEXT PRIMARY KEY, name TEXT NOT NULL, department TEXT NOT NULL, degree_credits INTEGER NOT NULL);
CREATE TABLE student (id TEXT PRIMARY KEY, external_ref TEXT UNIQUE NOT NULL, name TEXT NOT NULL, preferred_name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, program_id TEXT NOT NULL REFERENCES program, admit_term TEXT NOT NULL REFERENCES term, residency TEXT NOT NULL CHECK(residency IN ('in_state','out_of_state','international')), admit_type TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('applicant','admitted','enrolled','leave','withdrawn','denied')), birth_date TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE application (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, term_id TEXT NOT NULL REFERENCES term, status TEXT NOT NULL, submitted_at TEXT NOT NULL, decided_at TEXT, respond_by TEXT, CHECK(decided_at IS NULL OR decided_at>=submitted_at));
CREATE TABLE assignment (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, staff_id TEXT NOT NULL REFERENCES staff, role TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT, reason TEXT NOT NULL, CHECK(ends_at IS NULL OR ends_at>starts_at));
CREATE UNIQUE INDEX one_current_adviser ON assignment(student_id,role) WHERE ends_at IS NULL;
CREATE TABLE course (id TEXT PRIMARY KEY, code TEXT UNIQUE NOT NULL, title TEXT NOT NULL, credits INTEGER NOT NULL CHECK(credits BETWEEN 0 AND 6), level INTEGER NOT NULL, description TEXT NOT NULL);
CREATE TABLE prerequisite (course_id TEXT NOT NULL REFERENCES course, required_course_id TEXT NOT NULL REFERENCES course, minimum_grade TEXT NOT NULL, PRIMARY KEY(course_id,required_course_id), CHECK(course_id<>required_course_id));
CREATE TABLE requirement (id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES program, course_id TEXT REFERENCES course, category TEXT NOT NULL, recommended_term INTEGER, credits INTEGER NOT NULL CHECK(credits>=0), description TEXT NOT NULL);
CREATE TABLE section (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES course, term_id TEXT NOT NULL REFERENCES term, label TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0), weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6), start_minute INTEGER NOT NULL, end_minute INTEGER NOT NULL, room TEXT NOT NULL, modality TEXT NOT NULL CHECK(modality IN ('in_person','online')), status TEXT NOT NULL CHECK(status IN ('open','cancelled')), CHECK(end_minute>start_minute));
CREATE TABLE enrollment (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, section_id TEXT NOT NULL REFERENCES section, status TEXT NOT NULL CHECK(status IN ('enrolled','dropped','withdrawn','completed')), enrolled_at TEXT NOT NULL, ended_at TEXT, grade TEXT, version INTEGER NOT NULL DEFAULT 1, UNIQUE(student_id,section_id));
CREATE TABLE transfer_credit (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, course_id TEXT NOT NULL REFERENCES course, institution TEXT NOT NULL, credits INTEGER NOT NULL, grade TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','accepted','rejected')), received_at TEXT NOT NULL, evaluated_at TEXT, evaluator_id TEXT REFERENCES staff);
CREATE TABLE sap_evaluation (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, term_id TEXT NOT NULL REFERENCES term, attempted_credits INTEGER NOT NULL CHECK(attempted_credits>=0), earned_credits INTEGER NOT NULL CHECK(earned_credits BETWEEN 0 AND attempted_credits), gpa REAL, completion_rate REAL, maximum_attempted_credits INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('meeting','warning','suspension','not_evaluated')), previous_id TEXT REFERENCES sap_evaluation, evaluated_at TEXT NOT NULL, policy_id TEXT NOT NULL REFERENCES policy, UNIQUE(student_id,term_id));
CREATE TABLE waitlist (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, section_id TEXT NOT NULL REFERENCES section, position INTEGER NOT NULL CHECK(position>0), status TEXT NOT NULL CHECK(status IN ('waiting','offered','accepted','expired')), offered_at TEXT, expires_at TEXT, UNIQUE(section_id,position));
CREATE TABLE policy (id TEXT PRIMARY KEY, code TEXT NOT NULL, version TEXT NOT NULL, title TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES office, audience TEXT NOT NULL CHECK(audience IN ('student','internal','all')), authority TEXT NOT NULL CHECK(authority IN ('policy','procedure','guide','advisory')), effective_from TEXT NOT NULL, effective_until TEXT, published_at TEXT NOT NULL, supersedes_id TEXT REFERENCES policy, applies_json TEXT NOT NULL, body TEXT NOT NULL, source_path TEXT NOT NULL, content_hash TEXT NOT NULL, UNIQUE(code,version), CHECK(effective_until IS NULL OR effective_until>effective_from));
CREATE TABLE policy_link (policy_id TEXT NOT NULL REFERENCES policy, related_id TEXT NOT NULL REFERENCES policy, PRIMARY KEY(policy_id,related_id));
CREATE TABLE calendar (id TEXT PRIMARY KEY, term_label TEXT NOT NULL, title TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT, office_id TEXT NOT NULL REFERENCES office, policy_id TEXT NOT NULL REFERENCES policy, audience TEXT NOT NULL, category TEXT NOT NULL);
CREATE TABLE document (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, category TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('NOT_SUBMITTED','UPLOADED','UNDER_REVIEW','ACCEPTED','REJECTED','EXPIRED','WAIVED','NEEDS_RESUBMISSION')), office_id TEXT NOT NULL REFERENCES office, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE document_revision (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES document, revision INTEGER NOT NULL, status TEXT NOT NULL, effective_at TEXT NOT NULL, recorded_at TEXT NOT NULL, reason TEXT NOT NULL, source TEXT NOT NULL, UNIQUE(document_id,revision));
CREATE TABLE fund (id TEXT PRIMARY KEY, name TEXT NOT NULL, source TEXT NOT NULL, annual_cap_cents INTEGER NOT NULL CHECK(annual_cap_cents>0), posts_to_account INTEGER NOT NULL CHECK(posts_to_account IN (0,1)), international_eligible INTEGER NOT NULL CHECK(international_eligible IN (0,1)), policy_id TEXT NOT NULL REFERENCES policy);
CREATE TABLE award (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, fund_id TEXT NOT NULL REFERENCES fund, aid_year TEXT NOT NULL, offered_cents INTEGER NOT NULL CHECK(offered_cents>=0), accepted_cents INTEGER NOT NULL CHECK(accepted_cents BETWEEN 0 AND offered_cents), status TEXT NOT NULL CHECK(status IN ('offered','accepted','declined')), UNIQUE(student_id,fund_id,aid_year));
CREATE TABLE disbursement (id TEXT PRIMARY KEY, award_id TEXT NOT NULL REFERENCES award, term_id TEXT NOT NULL REFERENCES term, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), status TEXT NOT NULL CHECK(status IN ('scheduled','held','posted','reversed')), scheduled_at TEXT NOT NULL, posted_at TEXT, reason TEXT);
CREATE TABLE payment (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, term_id TEXT NOT NULL REFERENCES term, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), status TEXT NOT NULL CHECK(status IN ('pending','posted','failed','reversed')), submitted_at TEXT NOT NULL, settled_at TEXT, method TEXT NOT NULL, idempotency_key TEXT UNIQUE NOT NULL);
CREATE TABLE ledger (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, term_id TEXT NOT NULL REFERENCES term, kind TEXT NOT NULL CHECK(kind IN ('charge','payment','aid','refund','reversal','credit_adjustment')), amount_cents INTEGER NOT NULL, posted_at TEXT NOT NULL, due_at TEXT, payment_id TEXT REFERENCES payment, disbursement_id TEXT REFERENCES disbursement, reverses_id TEXT UNIQUE REFERENCES ledger, description TEXT NOT NULL, CHECK((kind IN ('charge','refund','reversal') AND amount_cents>0) OR (kind IN ('payment','aid','credit_adjustment') AND amount_cents<0)));
CREATE UNIQUE INDEX payment_posts_once ON ledger(payment_id) WHERE kind='payment';
CREATE UNIQUE INDEX aid_posts_once ON ledger(disbursement_id) WHERE kind='aid';
CREATE TABLE hold (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, term_id TEXT NOT NULL DEFAULT '2026FA' REFERENCES term, kind TEXT NOT NULL, office_id TEXT NOT NULL REFERENCES office, blocks_registration INTEGER NOT NULL CHECK(blocks_registration IN (0,1)), placed_at TEXT NOT NULL, released_at TEXT, reason TEXT NOT NULL, policy_id TEXT NOT NULL REFERENCES policy, version INTEGER NOT NULL DEFAULT 1, CHECK(released_at IS NULL OR released_at>=placed_at));
CREATE TABLE residence (id TEXT PRIMARY KEY, name TEXT NOT NULL, style TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0));
CREATE TABLE bed (id TEXT PRIMARY KEY, residence_id TEXT NOT NULL REFERENCES residence, room TEXT NOT NULL, accessible INTEGER NOT NULL CHECK(accessible IN (0,1)));
CREATE TABLE housing (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, term_id TEXT NOT NULL REFERENCES term, bed_id TEXT REFERENCES bed, status TEXT NOT NULL CHECK(status IN ('assigned','waitlisted','exempt','cancelled')), starts_at TEXT NOT NULL, ends_at TEXT, reason TEXT NOT NULL);
CREATE UNIQUE INDEX occupied_bed ON housing(bed_id,term_id) WHERE status='assigned' AND ends_at IS NULL;
CREATE UNIQUE INDEX one_housing ON housing(student_id,term_id) WHERE ends_at IS NULL;
CREATE TABLE consent (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, delegate_name TEXT NOT NULL, scope TEXT NOT NULL, starts_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, CHECK(expires_at>starts_at));
CREATE TABLE exception (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, policy_id TEXT NOT NULL REFERENCES policy, kind TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('requested','approved','denied','expired')), office_id TEXT NOT NULL REFERENCES office, approver_id TEXT REFERENCES staff, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, reason TEXT NOT NULL, CHECK(ends_at>starts_at), CHECK(status<>'approved' OR approver_id IS NOT NULL));
CREATE TABLE workflow (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, title TEXT NOT NULL, kind TEXT NOT NULL, office_id TEXT NOT NULL REFERENCES office, owner_id TEXT NOT NULL REFERENCES staff, status TEXT NOT NULL CHECK(status IN ('open','waiting','resolved','cancelled')), opened_at TEXT NOT NULL, due_at TEXT NOT NULL, resolved_at TEXT, policy_id TEXT NOT NULL REFERENCES policy, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE workflow_step (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflow, title TEXT NOT NULL, office_id TEXT NOT NULL REFERENCES office, status TEXT NOT NULL CHECK(status IN ('blocked','ready','complete','waived')), completed_at TEXT, evidence TEXT, CHECK(status NOT IN ('complete','waived') OR evidence IS NOT NULL));
CREATE TABLE step_dependency (step_id TEXT NOT NULL REFERENCES workflow_step, prerequisite_id TEXT NOT NULL REFERENCES workflow_step, PRIMARY KEY(step_id,prerequisite_id), CHECK(step_id<>prerequisite_id));
CREATE TABLE communication (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, workflow_id TEXT REFERENCES workflow, channel TEXT NOT NULL, direction TEXT NOT NULL, delivery TEXT NOT NULL CHECK(delivery IN ('delivered','bounced','recorded','queued')), audience TEXT NOT NULL CHECK(audience IN ('student','internal')), sent_at TEXT NOT NULL, body TEXT NOT NULL, authoritative INTEGER NOT NULL CHECK(authoritative IN (0,1)));
CREATE TABLE appointment (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, staff_id TEXT NOT NULL REFERENCES staff, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('scheduled','completed','cancelled','no_show')), purpose TEXT NOT NULL, CHECK(ends_at>starts_at));
CREATE TABLE event (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, effective_at TEXT NOT NULL, recorded_at TEXT NOT NULL, actor TEXT NOT NULL, from_state TEXT, to_state TEXT NOT NULL, description TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('student','internal')), correlation_id TEXT NOT NULL);
CREATE TABLE source_issue (id TEXT PRIMARY KEY, severity TEXT NOT NULL, domain TEXT NOT NULL, title TEXT NOT NULL, finding TEXT NOT NULL, resolution TEXT NOT NULL, intentional INTEGER NOT NULL CHECK(intentional IN (0,1)));
CREATE TABLE action_receipt (idempotency_key TEXT PRIMARY KEY, request_json TEXT NOT NULL, result_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX event_student_clock ON event(student_id,recorded_at,effective_at);
CREATE INDEX enrollment_student ON enrollment(student_id,status);
CREATE INDEX ledger_student ON ledger(student_id,posted_at);
CREATE INDEX workflow_due ON workflow(status,due_at);
CREATE INDEX document_student ON document(student_id);
CREATE INDEX hold_student ON hold(student_id,released_at);
CREATE INDEX assignment_staff ON assignment(staff_id,ends_at);
CREATE VIEW account_balance AS SELECT student_id,term_id,SUM(amount_cents) AS balance_cents FROM ledger GROUP BY student_id,term_id;
CREATE VIEW current_load AS SELECT e.student_id,s.term_id,SUM(c.credits) AS credits FROM enrollment e JOIN section s ON s.id=e.section_id JOIN course c ON c.id=s.course_id WHERE e.status='enrolled' GROUP BY e.student_id,s.term_id;
CREATE VIEW academic_progress AS SELECT e.student_id,SUM(c.credits) AS attempted_credits,SUM(CASE WHEN e.grade IN ('A','B','C','D','P') THEN c.credits ELSE 0 END) AS earned_credits,ROUND(SUM(CASE e.grade WHEN 'A' THEN c.credits*4 WHEN 'B' THEN c.credits*3 WHEN 'C' THEN c.credits*2 WHEN 'D' THEN c.credits ELSE 0 END)*1.0/NULLIF(SUM(CASE WHEN e.grade IN ('A','B','C','D','F') THEN c.credits ELSE 0 END),0),3) AS gpa FROM enrollment e JOIN section s ON s.id=e.section_id JOIN course c ON c.id=s.course_id WHERE e.status IN ('completed','withdrawn') GROUP BY e.student_id;
PRAGMA user_version = 1;
